const rulersData=[{name:"Chandragupta Maurya",era:"Ancient",dynasty:"Maurya",region:"Pan-Indian",reign:"c. 321 – 297 BCE",image:"ruler-ashoka..jpg",description:"Founder of the Mauryan Empire and unifier of ancient India. Mentored by Chanakya, he overthrew Nanda rule, repelled Seleucus I Nicator, and established a centralized subcontinental state.",link:"../chandragupta-maurya-explorer/index.html"},{name:"Ashoka the Great",era:"Ancient",dynasty:"Maurya",region:"Pan-Indian",reign:"c. 268 – 232 BCE",image:"ruler-ashoka..jpg",description:"Expanded the Mauryan Empire across the subcontinent before renouncing war after Kalinga. Spread messages of Dhamma (Buddhism) through his famous rock and pillar edicts.",link:"../ashoka-the-great-explorer/index.html"},{name:"Samudragupta",era:"Ancient",dynasty:"Gupta",region:"North India",reign:"c. 335 – 375 CE",image:"../assets/samudragupta_veena_coin.jpg",description:"A brilliant military tactician and patron of the arts. His reign laid the foundation for the 'Golden Age of India', and he was known for his poetry and musical skills.",link:"../samudragupta-explorer/index.html"},{name:"Chandragupta II Vikramaditya",era:"Ancient",dynasty:"Gupta",region:"Pan-Indian",reign:"c. 375 – 415 CE",image:"../assets/gupta_gold_coin.jpg",description:"Vanquished the Western Kshatrapas, extended Gupta rule from coast to coast, ushered in classical India's Golden Age, and commissioned the Mehrauli Iron Pillar.",link:"../chandragupta-ii-explorer/index.html"},{name:"Rajaraja Chola I",era:"Early Medieval",dynasty:"Chola",region:"South India",reign:"985 – 1014 CE",image:"ruler-rajaraja.jpg",description:"Transformed the Chola dynasty into a formidable maritime empire. He commissioned the monumental Brihadisvara Temple at Thanjavur, a UNESCO World Heritage site.",link:"../ruler/rajaraja-chola.html"},{name:"Krishnadevaraya",era:"Medieval",dynasty:"Vijayanagara",region:"South India",reign:"1509 – 1529 CE",image:"ruler-krishnadevaraya..jpg",description:"The greatest emperor of the Vijayanagara Empire. A military genius and a celebrated scholar, his reign saw exceptional architectural and literary achievements.",link:"../ruler/krishnadevaraya.html"},{name:"Akbar",era:"Medieval",dynasty:"Mughal",region:"Pan-Indian",reign:"1556 – 1605 CE",image:"ruler-akbar..jpg",description:"Vastly expanded the Mughal Empire while pioneering policies of religious tolerance (Din-i-Ilahi) and establishing a robust centralized administrative system.",link:"../ruler/akbar.html"},{name:"Chhatrapati Shivaji Maharaj",era:"Early Modern",dynasty:"Maratha",region:"West India",reign:"1674 – 1680 CE",image:"ruler-shivaji..webp",description:"Carved an independent Maratha kingdom using innovative guerrilla warfare tactics and built a powerful navy and string of coastal forts to defend his territory.",link:"../ruler/shivaji.html"}];document.addEventListener("DOMContentLoaded",()=>{const a=document.getElementById("rulers-grid"),e=document.getElementById("search-ruler"),r=document.getElementById("filter-dynasty"),n=document.getElementById("filter-region"),i=document.getElementById("reset-filters"),t=document.querySelectorAll(".era-card");function l(e){a.innerHTML="",0!==e.length?e.forEach(e=>{const r=document.createElement("article");r.className="ruler-card",r.innerHTML=`\n        <img src="${e.image}" alt="Historical representation of ${e.name}" class="ruler-img" loading="lazy">\n        <div class="ruler-info">\n          <div class="ruler-tags">\n            <span class="ruler-tag">${e.dynasty}</span>\n            <span class="ruler-tag">${e.region}</span>\n          </div>\n          <h3>${e.name}</h3>\n          <span class="ruler-reign">${e.reign}</span>\n          <p class="ruler-desc">${e.description}</p>\n          <a href="${e.link}" class="btn-outline" aria-label="Explore history of ${e.name}">Explore →</a>\n        </div>\n      `,a.appendChild(r)}):a.innerHTML='<p style="grid-column: 1/-1; text-align:center; color: var(--rulers-text-muted);">No rulers found matching your criteria.</p>'}function s(){const a=e.value.toLowerCase(),i=r.value,t=n.value;l(rulersData.filter(e=>{const r=e.name.toLowerCase().includes(a)||e.dynasty.toLowerCase().includes(a),n="all"===i||e.dynasty===i,l="all"===t||e.region===t;return r&&n&&l}))}e.addEventListener("input",s),r.addEventListener("change",s),n.addEventListener("change",s),i.addEventListener("click",()=>{e.value="",r.value="all",n.value="all",l(rulersData)}),t.forEach(a=>{a.addEventListener("click",()=>{const i=a.getAttribute("data-era");l(rulersData.filter(a=>a.era===i)),document.getElementById("explore-rulers").scrollIntoView({behavior:"smooth"}),e.value="",r.value="all",n.value="all"})}),l(rulersData)});